const copy = (response) => response === null ? null : [...response];

export function outcome(question, response) {
  if (response === null) return 'unanswered';
  const expected = question.answer.optionIds;
  const actual = question.type === 'multiple-select' ? [...response].sort() : response;
  const reference = question.type === 'multiple-select' ? [...expected].sort() : expected;
  return actual.length === reference.length && actual.every((id, index) => id === reference[index]) ? 'correct' : 'revisit';
}

export class QuizSession {
  constructor(quiz) {
    this.quiz = quiz;
    this.activeIndex = 0;
    this.viewIndex = 0;
    this.mode = 'session';
    this.records = quiz.payload.questions.map((question) => ({
      phase: 'attempt', response: null,
      draft: question.type === 'ordering' ? question.options.map((option) => option.id) : [],
      openedSources: new Set(),
    }));
  }
  get question() { return this.quiz.payload.questions[this.viewIndex]; }
  get record() { return this.records[this.viewIndex]; }
  get complete() { return this.records.every((record) => record.phase === 'revealed'); }

canAnswer(response = this.record.draft) {
  if (!Array.isArray(response)) return false;
  const allowed = this.question.options.map((option) => option.id);
  if (new Set(response).size !== response.length || response.some((id) => !allowed.includes(id))) return false;
  if (this.question.type === 'single-choice') return response.length === 1;
  if (this.question.type === 'multiple-select') return response.length >= 1;
  return response.length === allowed.length;
}
setDraft(response) {
  if (this.record.phase === 'revealed') throw new Error('Revealed answers cannot be changed.');
  const allowed = this.question.options.map((option) => option.id);
  if (!Array.isArray(response) || new Set(response).size !== response.length || response.some((id) => !allowed.includes(id))) throw new Error('Invalid response.');
  if (this.question.type === 'single-choice' && response.length > 1) throw new Error('Choose one answer.');
  if (this.question.type === 'ordering' && response.length !== allowed.length) throw new Error('Keep every ordering item.');
  this.record.draft = copy(response);
}
reveal(unsure = false) {
  if (this.record.phase !== 'attempt') throw new Error('This answer is already revealed.');
  if (!unsure && !this.canAnswer()) throw new Error('Choose an answer or reveal as unsure.');
  this.record.response = unsure ? null : copy(this.record.draft);
  this.record.phase = 'revealed';
}

  next() {
    if (this.viewIndex !== this.activeIndex || this.record.phase !== 'revealed') throw new Error('Reveal the current answer before advancing.');
    if (this.activeIndex === this.records.length - 1) this.mode = 'recap';
    else { this.activeIndex++; this.viewIndex = this.activeIndex; }
  }
  review(index) {
    if (!Number.isInteger(index) || index < 0 || index > this.activeIndex || (index !== this.activeIndex && this.records[index].phase !== 'revealed')) throw new Error('That question is not yet available.');
    this.viewIndex = index;
    this.mode = 'session';
  }
  recap() {
    if (!this.complete) throw new Error('Complete the quiz before opening its recap.');
    this.mode = 'recap';
  }
}

function el(tag, properties = {}, ...children) {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(properties)) {
    if (value === false || value == null) continue;
    if (key.startsWith('on')) node.addEventListener(key.slice(2).toLowerCase(), value);
    else if (key === 'class') node.className = value;
    else if (key === 'checked') node.checked = value;
    else node.setAttribute(key, value === true ? '' : String(value));
  }
  for (const child of children.flat(Infinity)) {
    if (child != null && child !== false) node.append(child instanceof Node ? child : document.createTextNode(String(child)));
  }
  return node;
}

function acceptQuiz(candidate) {
  const replace = () => { quiz = candidate; session = null; clearError(); render(); focus(); say('Quiz package ready.'); };
  if (session) confirm('Replace this session?', 'Its answers and progress will be cleared.', 'Replace session', replace);
  else replace();
}
async function load(importer) {
  const sequence = ++importSequence;
  importing = true;
  openButton.disabled = true;
  clearError();
  say('Checking quiz package.');
  try {
    const candidate = await importer();
    if (sequence === importSequence) acceptQuiz(candidate);
  } catch (error) {
    if (sequence === importSequence) showError(error);
  } finally {
    if (sequence === importSequence) {
      importing = false;
      openButton.disabled = false;
    }
  }
}
openButton.addEventListener('click', () => fileInput.click());
fileInput.addEventListener('change', () => {
  const file = fileInput.files[0];
  fileInput.value = '';
  if (!file) return;
  load(async () => {
    if (file.size > MAX_PACKAGE_BYTES) throw new PackageError('package-too-large', 'Quiz packages must be 10 MiB or smaller.');
    return importPackageBytes(await file.arrayBuffer());
  });

const outcomeLabel = (value) => value === 'correct' ? 'Correct' : value === 'unanswered' ? 'Not answered' : 'Worth revisiting';
function resultView(question, record) {
  const result = outcome(question, record.response);
  const section = el('section', { class: `answer-section ${result}`, 'aria-labelledby': 'answer-heading' },
    el('div', { class: 'outcome-heading' }, el('h2', { id: 'answer-heading', tabindex: '-1' }, outcomeLabel(result))),
    el('p', { class: 'answer-explanation' }, question.answer.explanation));
  const order = question.type === 'ordering' ? question.answer.optionIds : question.options.map((option) => option.id);
  const answerList = el(question.type === 'ordering' ? 'ol' : 'ul', { class: 'answer-list' });
  for (const id of order) {
    const option = question.options.find((item) => item.id === id);
    const expected = question.answer.optionIds.includes(id);
    const chosen = record.response?.includes(id);
    const feedback = question.answer.optionFeedback.find((item) => item.optionId === id);
    answerList.append(el('li', { class: expected ? 'expected' : '' },
      el('div', { class: 'answer-option' }, el('strong', {}, option.text),
        question.type !== 'ordering' && el('span', { class: 'answer-label' }, expected ? (chosen ? 'Expected · Selected' : 'Expected answer') : chosen ? 'Selected · Reconsider' : 'Alternative')),
      el('p', {}, feedback.explanation)));
  }
  section.append(el('h3', {}, question.type === 'ordering' ? 'Reference sequence' : 'Answer details'), answerList);
  if (question.type === 'ordering') {
    section.append(el('p', { class: 'response-summary' }, 'Your sequence: ', record.response ? record.response.map((id) => question.options.find((item) => item.id === id).text).join(' → ') : 'Not answered'));
  }
  return section;

function sourceDetail(source, record, reason, prefix) {
  const details = el('details', { class: 'source-detail', id: `${prefix}-${source.id}`, open: record?.openedSources.has(source.id) },
    el('summary', {}, el('span', { class: 'source-filename' }, source.path.split('/').at(-1)),
      el('span', { class: 'source-range' }, `Lines ${source.startLine}–${source.endLine}`)),
    el('p', { class: 'source-path' }, source.path));
  if (reason) details.append(el('p', { class: 'source-reason' }, reason));
  const code = el('code');
  source.code.split('\n').forEach((line, index) => code.append(el('span', { class: 'code-line' },
    el('span', { class: 'line-number', 'aria-hidden': 'true' }, source.startLine + index), el('span', { class: 'line-text' }, line || ' '))));
  details.append(el('pre', { tabindex: '0', 'aria-label': `${source.path}, lines ${source.startLine} through ${source.endLine}` }, code));
  if (source.url) details.append(el('a', { class: 'source-link', href: source.url, target: '_blank', rel: 'noopener noreferrer', 'aria-label': `Open ${source.path} at this commit (opens in new tab)` }, 'Open at this commit ↗'));

function sourcePanel(question, record) {
  const ids = [...new Set([...question.answer.evidence.map((item) => item.sourceId), ...question.discussion.flatMap((topic) => topic.sourceIds)])];
  const panel = el('aside', { class: 'source-panel', 'aria-labelledby': 'source-title' },
    el('h2', { id: 'source-title' }, 'Source references'));
  for (const id of ids) {
    const source = quiz.payload.sources.find((item) => item.id === id);
    const reason = question.answer.evidence.find((item) => item.sourceId === id)?.reason;
    panel.append(sourceDetail(source, record, reason, 'question-source'));
  }
  return panel;
}
function discussionView(question) {
  return el('section', { class: 'discussion-section', 'aria-labelledby': 'discussion-title' },
    el('h2', { id: 'discussion-title' }, 'Discuss together'),
    el('ol', {}, question.discussion.map((topic) => el('li', {}, el('p', {}, topic.prompt),
      el('div', { class: 'discussion-sources' }, topic.sourceIds.map((id) => {
        const source = quiz.payload.sources.find((item) => item.id === id);
        return button(`Inspect ${source.path.split('/').at(-1)}`, () => inspectSource(id), 'text');
      }))))));
}

function questionView(main) {
  const question = session.question;
  const record = session.record;
  const concepts = question.conceptIds.map((id) => quiz.payload.learning.coverage.find((item) => item.id === id).title);
  main.append(el('div', { class: 'question-topline' },
    el('p', { class: 'eyebrow' }, `Question ${session.viewIndex + 1} of ${session.records.length}`),
    el('p', { class: 'concept-label' }, concepts[0])));
  const layout = el('div', { class: `question-layout ${record.phase === 'attempt' ? 'attempt-layout' : ''}` });
  const work = el('div', { class: 'question-workspace' }, el('h1', { id: 'page-title', tabindex: '-1' }, question.prompt));
  if (record.phase === 'revealed') work.append(resultView(question, record), discussionView(question));
  else {
    work.append(responseControls(question, record),
      el('div', { class: 'actions question-actions' },
        button('Reveal answer', () => {
          session.reveal(); render(); focus('answer-heading'); say(`Answer revealed. ${outcomeLabel(outcome(question, record.response))}.`);
        }, 'primary', { id: 'submit-response', disabled: !session.canAnswer() }),
        button('I’m not sure', () => {
          session.reveal(true); render(); focus('answer-heading'); say('Answer revealed. Not answered.');
        }, 'text')));
  }
  if (record.phase === 'revealed') {
    const nextAction = session.complete ? button(session.viewIndex === session.activeIndex ? 'View learning recap' : 'Back to learning recap', () => { session.recap(); render(); focus(); }, 'primary')
      : session.viewIndex !== session.activeIndex ? button('Return to current question', () => { session.review(session.activeIndex); render(); focus(); }, 'primary')
        : button(session.activeIndex === session.records.length - 1 ? 'View learning recap' : 'Next question', () => { session.next(); render(); focus(); }, 'primary');
    work.append(el('div', { class: 'next-action' }, nextAction));
  }
  layout.append(work);
  if (record.phase === 'revealed') layout.append(sourcePanel(question, record));
  main.append(layout);

import validateStructure from '../generated/package-validator.js';
import { PackageError } from './errors.js';
import { parseStrictJson } from './strict-json.js';
import { canonicalize, payloadDigest } from './canonical.js';

export const MAX_PACKAGE_BYTES = 10 * 1024 * 1024;
const fail = (code, message, path = '') => { throw new PackageError(code, message, path); };

export async function validatePackage(data) {
  if (!data || Array.isArray(data) || typeof data !== 'object') fail('invalid-structure', 'A quiz package must be a JSON object.');
  canonicalize(data); // Reject invalid Unicode and unsafe numbers throughout.
  if (data.formatVersion !== '1.0') fail('unsupported-version', 'This viewer supports quiz package version 1.0.', '/formatVersion');
  if (!data.verification || data.verification.status !== 'passed' || data.verification.method !== 'independent-subagent') {
    fail('incomplete-verification', 'A passed independent-subagent review is required before this quiz can start.', '/verification');
  }
  if (!validateStructure(data)) {
    const error = validateStructure.errors[0];
    const path = error.instancePath || '/';
    const code = path.startsWith('/verification') ? 'incomplete-verification' : 'invalid-structure';
    fail(code, `Package field ${path} ${error.message}.`, path);
  }

for (const question of payload.questions) {
  const path = `/payload/questions/${question.id}`;
  const options = question.options.map((option) => option.id);
  unique(options, `${path}/options`);
  const optionIds = new Set(options);
  references(question.conceptIds, concepts, `${path}/conceptIds`);
  references(question.explorationSourceIds, sources, `${path}/explorationSourceIds`);
  references(question.answer.optionIds, optionIds, `${path}/answer/optionIds`);
  references(question.answer.evidence.map((item) => item.sourceId), sources, `${path}/answer/evidence`);
  const feedback = question.answer.optionFeedback.map((item) => item.optionId);
  references(feedback, optionIds, `${path}/answer/optionFeedback`);
  if (feedback.length !== options.length) fail('invalid-answer', 'Every answer option needs feedback.', path);
  for (const topic of question.discussion) references(topic.sourceIds, sources, `${path}/discussion`);
  if (question.type === 'ordering') {
    if (question.answer.optionIds.length !== options.length) fail('invalid-answer', 'An ordering answer must contain every item exactly once.', path);
    if (question.answer.optionIds.every((id, index) => id === options[index])) fail('invalid-answer', 'Initial item order must differ from the reference answer.', path);
  } else if (question.answer.optionIds.length === options.length) fail('invalid-answer', 'A choice question must contain an incorrect alternative.', path);
}
if (verification.verifierId === payload.preparation.generatorId || verification.sourceCommitSha !== payload.repository.commitSha || !verification.independentSolutionsRecorded) {
  fail('incomplete-verification', 'Review identity, source revision, and independent-solving declaration must match the preparation requirements.', '/verification');
}
const questionIds = new Set(payload.questions.map((question) => question.id));
references(verification.questionReviews.map((review) => review.questionId), questionIds, '/verification/questionReviews');
if (verification.questionReviews.length !== questionIds.size) fail('incomplete-verification', 'Every question needs its own passed review.', '/verification/questionReviews');
for (const review of verification.questionReviews) {
  references(review.evidenceSourceIds, sources, `/verification/${review.questionId}`);
  const question = payload.questions.find((item) => item.id === review.questionId);
  if (question.answer.evidence.some((item) => !review.evidenceSourceIds.includes(item.sourceId))) {
    fail('incomplete-verification', 'Question review must cover all answer evidence.', `/verification/${review.questionId}`);
  }
}
if (await payloadDigest(payload) !== verification.reviewedPayloadSha256) {
  fail('stale-verification', 'Quiz content changed after its recorded review. Prepare and verify the package again.', '/verification/reviewedPayloadSha256');

export async function importPackageText(text) {
  if (new TextEncoder().encode(text).byteLength > MAX_PACKAGE_BYTES) fail('package-too-large', 'Quiz packages must be 10 MiB or smaller.');
  return validatePackage(parseStrictJson(text));
}

export async function importPackageBytes(bytes) {
  if (bytes.byteLength > MAX_PACKAGE_BYTES) fail('package-too-large', 'Quiz packages must be 10 MiB or smaller.');
  let text;
  try { text = new TextDecoder('utf-8', { fatal: true }).decode(bytes); }
  catch { fail('invalid-json', 'The quiz package must be a valid UTF-8 text file.'); }
  return importPackageText(text);
}

const string = () => {
  const start = position++;
  while (position < text.length) {
    if (text[position] === '\\') position += 2;
    else if (text[position++] === '"') {
      try { return JSON.parse(text.slice(start, position)); }
      catch { fail('Invalid string'); }
    }
  }
  fail('Unterminated string');
};

import { readFile, mkdir, writeFile } from 'node:fs/promises';
import Ajv2020 from 'ajv/dist/2020.js';
import standalone from 'ajv/dist/standalone/index.js';

const schema = JSON.parse(await readFile(new URL('../schema/quiz-package-v1.schema.json', import.meta.url), 'utf8'));
const ajv = new Ajv2020({ strict: true, allErrors: true, code: { source: true, esm: true } });
let code = standalone(ajv, ajv.compile(schema));
// Ajv's standalone runtime helpers use require even with ESM exports. Convert
// these fixed compiler-generated imports so Node and Vite share the same output.
code = code.replace(/const (\w+) = require\("(ajv\/dist\/runtime\/[^".]+)"\)\.default;/g,
  (_, name, path) => `import ${name}Module from '${path}.js'; const ${name} = ${name}Module.default ?? ${name}Module;`);
if (code.includes('require(')) throw new Error('Unexpected standalone validator dependency.');
await mkdir(new URL('../src/generated/', import.meta.url), { recursive: true });
await writeFile(new URL('../src/generated/package-validator.js', import.meta.url), code);
console.log('Compiled the v1 package schema.');

import { mkdir, readFile, writeFile, copyFile, rm } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { build } from 'vite';
import { bundledDependencyNotices } from './build-licenses.mjs';

const source = new URL('../skills/code-bearings-quiz/', import.meta.url);
const destination = new URL('../.skill-build/code-bearings-quiz/', import.meta.url);
await rm(destination, { recursive: true, force: true });
for (const directory of ['references/', 'scripts/', 'assets/']) await mkdir(new URL(directory, destination), { recursive: true });
const files = ['SKILL.md', 'references/preparation.md', 'references/package-contract.md'];
for (const file of files) {
  const content = await readFile(new URL(file, source), 'utf8');
  const schemaPath = file === 'SKILL.md' ? '../../schema/quiz-package-v1.schema.json' : '../../../schema/quiz-package-v1.schema.json';
  if (!content.includes(schemaPath)) throw new Error(`Expected schema link missing from ${file}.`);
  const portablePath = file === 'SKILL.md' ? 'assets/quiz-package-v1.schema.json' : '../assets/quiz-package-v1.schema.json';
  await writeFile(new URL(file, destination), content.replaceAll(schemaPath, portablePath));
}
await copyFile(new URL('../schema/quiz-package-v1.schema.json', import.meta.url), new URL('assets/quiz-package-v1.schema.json', destination));
await copyFile(new URL('../LICENSE', import.meta.url), new URL('LICENSE', destination));
await writeFile(new URL('assets/third-party-notices.txt', destination), await bundledDependencyNotices());
await build({
  configFile: false,
  publicDir: false,
  ssr: { noExternal: true },
  build: {
    ssr: fileURLToPath(new URL('scripts/quiz-tools.mjs', source)),
    outDir: fileURLToPath(new URL('scripts/', destination)),
    target: 'node22', minify: false, emptyOutDir: true,
    rolldownOptions: { output: { format: 'es', entryFileNames: 'quiz-tools.mjs' } },
  },
});
console.log('Portable skill built at .skill-build/code-bearings-quiz/.');

